{"command": "create", "path": "/app/workspace/extract.py", "file_text": """"Extract date and total_amount from receipt images and write to Excel."""
import os
import re
from datetime import date
from decimal import Decimal

import pandas as pd
import pytesseract
from PIL import Image, ImageFilter, ImageOps


IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"


# ------------------------- OCR -------------------------

def ocr_variants(img_path):
    """Multi-pass OCR producing a list of text results."""
    img = Image.open(img_path)
    # Upscale small images for better OCR
    if img.width < 1200:
        scale = 2
        img = img.resize((img.width * scale, img.height * scale), Image.Resampling.LANCZOS)

    gray = img.convert("L")
    variants = [
        gray,
        ImageOps.autocontrast(gray),
        gray.filter(ImageFilter.SHARPEN),
    ]
    psm_modes = ["--psm 6", "--psm 4"]

    texts = []
    for v in variants:
        for psm in psm_modes:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    texts.append(t)
            except Exception:
                pass
    return texts


# ------------------------- Date -------------------------

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

DATE_PATTERNS = [
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    (re.compile(r"\b(\d{1,2})[\s]*[/\-\.][\s]*(\d{1,2})[\s]*[/\-\.][\s]*(\d{4})\b"), "dmy4"),
    # YYYY-MM-DD, YYYY/MM/DD
    (re.compile(r"\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b"), "ymd"),
    # DD/MM/YY
    (re.compile(r"\b(\d{1,2})[\s]*[/\-][\s]*(\d{1,2})[\s]*[/\-][\s]*(\d{2})\b"), "dmy2"),
    # DD MMM YYYY (e.g., 1 Jan 2018)
    (re.compile(
        r"\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})\b",
        re.IGNORECASE), "dmy_text"),
]


def try_date(d, mo, y):
    if y < 100:
        y = 2000 + y if y < 50 else 1900 + y
    # If month>12 and day<=12, swap (OCR might confuse DD/MM vs MM/DD)
    if mo > 12 and d <= 12:
        d, mo = mo, d
    try:
        return date(y, mo, d).isoformat()
    except ValueError:
        return None


def extract_date(texts):
    # Prefer dates that look like receipt date; search near "DATE" keyword first
    for text in texts:
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(text):
                g = m.groups()
                try:
                    if kind == "dmy4":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "ymd":
                        y, mo, d = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "dmy2":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "dmy_text":
                        d = int(g[0])
                        mo = MONTHS[g[1].lower()[:3]]
                        y = int(g[2])
                    iso = try_date(d, mo, y)
                    if iso and 2000 <= int(iso[:4]) <= 2030:
                        return iso
                except Exception:
                    pass
    return None


# ------------------------- Amount -------------------------

# Keyword priority tiers (lower = higher priority)
KEYWORD_TIERS = [
    (1, ["GRAND TOTAL"]),
    (2, ["TOTAL RM", "TOTAL: RM"]),
    (3, ["TOTAL AMOUNT"]),
    (4, ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
         "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"]),
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "SST", "DISCOUNT",
    "CHANGE", "CASH TENDERED",
]

# Pattern "N% GST" means this line reports a GST amount (not total)
GST_SUMMARY_PAT = re.compile(r"\d+(?:\.\d+)?\s*%\s*GST", re.IGNORECASE)

# Positive context for GST (OK to keep): "incl GST", "Includes GST", "Inclusive of GST", "including GST"
GST_OK_PAT = re.compile(
    r"(incl(?:udes?|usive|\.?)|including)\.?\s*(?:of\s+)?GST",
    re.IGNORECASE)


# Match monetary numbers like 1,234.56 or 234.56 or 234,56 (OCR period->comma)
NUMBER_PAT = re.compile(r"\d{1,3}(?:,\d{3})+\.\d{1,2}|\d+\.\d{1,2}|\d+,\d{2}(?!\d)")


def parse_amount(s):
    s = s.strip().replace(" ", "")
    s = re.sub(r"^RM", "", s, flags=re.IGNORECASE)
    if "." in s and "," in s:
        s = s.replace(",", "")  # thousands separator
    elif "," in s:
        parts = s.split(",")
        if len(parts) == 2 and len(parts[1]) == 2:
            s = s.replace(",", ".")  # OCR decimal
        else:
            s = s.replace(",", "")
    try:
        return Decimal(s)
    except Exception:
        return None


def line_matches_keyword(upper_line, keywords):
    """Return the earliest position of any keyword match, or None."""
    best_pos = None
    for kw in keywords:
        p = upper_line.find(kw)
        if p >= 0:
            # Avoid matching "TOTAL" inside "SUBTOTAL" / "SUB TOTAL"
            if kw == "TOTAL":
                if p >= 3 and upper_line[p - 3:p] == "SUB":
                    continue
                if p >= 4 and upper_line[p - 4:p - 1] == "SUB":  # "SUB TOTAL"
                    continue
            if best_pos is None or p < best_pos:
                best_pos = p
    return best_pos


def is_excluded(upper_line, keyword_pos):
    """Check if line should be excluded due to exclusion keywords before keyword."""
    for ex in EXCLUSION_KEYWORDS:
        p = upper_line.find(ex)
        if p >= 0 and p < keyword_pos:
            return True
    # Lines like "SUB TOTAL" / "SUBTOTAL" are excluded regardless
    if "SUBTOTAL" in upper_line or "SUB TOTAL" in upper_line:
        return True
    # GST summary pattern (e.g., "6% GST 0.48")
    if GST_SUMMARY_PAT.search(upper_line):
        return True
    # If the line has GST but not in positive context (incl/includes/inclusive)
    if "GST" in upper_line and not GST_OK_PAT.search(upper_line):
        # Only exclude if GST appears before the keyword position too close
        # Actually: safer to exclude if GST is the dominant content
        # Keep for now, GST_SUMMARY_PAT handles the N% GST case
        pass
    return False


def extract_amount_from_texts(texts):
    """Return amount string with 2 decimals, or None."""
    best_overall = None  # (priority, chosen_decimal)

    for text in texts:
        lines = text.split("\n")
        # Collect candidates per priority
        for prio, kws in KEYWORD_TIERS:
            tier_candidates = []  # (line_idx, value, line)
            for i, line in enumerate(lines):
                upper = line.upper()
                pos = line_matches_keyword(upper, kws)
                if pos is None:
                    continue
                if is_excluded(upper, pos):
                    continue

                # Try to find a number on this line AFTER the keyword
                after_kw = line[pos:]
                nums = NUMBER_PAT.findall(after_kw)
                value = None
                if nums:
                    # Use the last number on the line
                    value = parse_amount(nums[-1])
                else:
                    # Try next non-empty line
                    for j in range(i + 1, min(i + 3, len(lines))):
                        nxt = lines[j].strip()
                        if nxt:
                            nxt_nums = NUMBER_PAT.findall(nxt)
                            if nxt_nums:
                                value = parse_amount(nxt_nums[-1])
                            break
                if value is None or value <= 0:
                    continue
                tier_candidates.append((i, value, line))

            if tier_candidates:
                # Select best within tier: prefer last if close to max, else max
                max_v = max(c[1] for c in tier_candidates)
                # Prefer the LAST candidate if it's within 20% of the max (rounded total case).
                last_v = tier_candidates[-1][1]
                if last_v >= max_v * Decimal("0.8"):
                    chosen = last_v
                else:
                    chosen = max_v

                if best_overall is None or prio < best_overall[0]:
                    best_overall = (prio, chosen)
                # Within same text, higher-priority tiers are preferred;
                # break out of tier loop for this text once we have a hit?
                # Actually we want best priority across all texts/variants, so continue.
                break  # found best tier for this text

    if best_overall is None:
        return None
    return f"{best_overall[1]:.2f}"


# ------------------------- Main -------------------------

def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        texts = ocr_variants(path)
        d = extract_date(texts)
        a = extract_amount_from_texts(texts)
        print(f"{fname}: date={d}, amount={a}")
        rows.append({"filename": fname, "date": d, "total_amount": a})

    df = pd.DataFrame(rows, columns=["filename", "date", "total_amount"])
    df.to_excel(OUT_XLSX, sheet_name="results", index=False)
    print(f"Wrote {OUT_XLSX}")


if __name__ == "__main__":
    main()
