    gray = img.convert("L")
    variants = [
        gray,
        ImageOps.autocontrast(gray),
        gray.filter(ImageFilter.SHARPEN),
    ]
    psm_modes = ["--psm 6", "--psm 4"]

    texts = []
    for v in variants:
        for psm in psm_modes:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    texts.append(t)
            except Exception:
                pass
    return texts


# ------------------------- Date -------------------------

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

DATE_PATTERNS = [
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    (re.compile(r"\b(\d{1,2})[\s]*[/\-\.][\s]*(\d{1,2})[\s]*[/\-\.][\s]*(\d{4})\b"), "dmy4"),
    # YYYY-MM-DD, YYYY/MM/DD
    (re.compile(r"\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b"), "ymd"),
    # DD/MM/YY
    (re.compile(r"\b(\d{1,2})[\s]*[/\-][\s]*(\d{1,2})[\s]*[/\-][\s]*(\d{2})\b"), "dmy2"),
    # DD MMM YYYY (e.g., 1 Jan 2018)
    (re.compile(
        r"\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})\b",
        re.IGNORECASE), "dmy_text"),
]


def try_date(d, mo, y):
    if y < 100:
        y = 2000 + y if y < 50 else 1900 + y
    # If month>12 and day<=12, swap (OCR might confuse DD/MM vs MM/DD)
    if mo > 12 and d <= 12:
        d, mo = mo, d
    try:
        return date(y, mo, d).isoformat()
    except ValueError:
        return None


def extract_date(texts):
    # Prefer dates that look like receipt date; search near "DATE" keyword first
    for text in texts:
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(text):
                g = m.groups()
                try:
                    if kind == "dmy4":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "ymd":
                        y, mo, d = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "dmy2":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                    elif kind == "dmy_text":
                        d = int(g[0])
                        mo = MONTHS[g[1].lower()[:3]]
