GST_SUMMARY_PAT = re.compile(r"\d+(?:\.\d+)?\s*%\s*GST", re.IGNORECASE)

# Positive context for GST (OK to keep): "incl GST", "Includes GST", "Inclusive of GST", "including GST"
GST_OK_PAT = re.compile(
    r"(incl(?:udes?|usive|\.?)|including)\.?\s*(?:of\s+)?GST",
    re.IGNORECASE)


