    # Collapse "123 . 45" / "123. 45" / "123 .45" into "123.45"
    text = re.sub(r"(\d)\s*\.\s*(\d{2})\b", r"\1.\2", text)
    # Collapse "123 , 45" / "123, 45" / "123 ,45" into "123,45"
    text = re.sub(r"(\d)\s*,\s*(\d{2})\b(?!\d)", r"\1,\2", text)
    return text


