    if y < 100:
        y = 2000 + y if y < 50 else 1900 + y
    if mo > 12 and d <= 12:
        d, mo = mo, d
    try:
        dt = date(y, mo, d)
    except ValueError:
        return None
    if not (2000 <= y <= 2030):
        return None
    return dt.isoformat()


def extract_date(texts):
    """Collect date candidates across variants; pick by consensus/score."""
    candidates = Counter()  # iso -> count
    day_width = {}  # iso -> average day digit count

    for text in texts:
        text = normalize_text(text)
        seen_in_this_text = set()
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(text):
                g = m.groups()
                try:
                    if kind == "dmy4":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                        dd_width = len(g[0])
                    elif kind == "ymd":
                        y, mo, d = int(g[0]), int(g[1]), int(g[2])
                        dd_width = len(g[2])
                    elif kind == "dmy2":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
