                    pass

    if not candidates:
        return None

    # Pick: higher count, then higher day_width (prefer "30" over "3"), then earliest
    best = sorted(
        candidates.items(),
        key=lambda kv: (-kv[1], -day_width.get(kv[0], 1), kv[0]),
    )[0][0]
    return best


# ------------------------- Amount -------------------------

KEYWORD_TIERS = [
    (1, ["GRAND TOTAL"]),
    (2, ["TOTAL RM", "TOTAL: RM"]),
    (3, ["TOTAL AMOUNT"]),
    (4, ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
