HEADER_INDICATORS = re.compile(
    r"\b(TAX\b|CODE\b|QTY\b|QUANTITY\b|U/\(RM\)|UNIT\b|PRICE\b|RATE\b)",
    re.IGNORECASE)

NUMBER_PAT = re.compile(
    r"\d{1,3}(?:,\d{3})+\.\d{1,2}|\d+\.\d{1,2}|\d+,\d{2}(?!\d)")


def parse_amount(s):
    s = s.strip().replace(" ", "")
    s = re.sub(r"^RM", "", s, flags=re.IGNORECASE)
    if "." in s and "," in s:
        s = s.replace(",", "")
    elif "," in s:
        parts = s.split(",")
        if len(parts) == 2 and len(parts[1]) == 2:
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return Decimal(s)
    except Exception:
        return None


def line_matches_keyword(upper_line, keywords):
    best_pos = None
    for kw in keywords:
        start = 0
        while True:
            p = upper_line.find(kw, start)
            if p < 0:
                break
            # Avoid matching "TOTAL" that's actually part of "SUBTOTAL" / "SUB TOTAL"
            if kw == "TOTAL":
                if p >= 3 and upper_line[p - 3:p] == "SUB":
                    start = p + 1
                    continue
                if p >= 4 and upper_line[p - 4:p] == "SUB ":
                    start = p + 1
                    continue
            if best_pos is None or p < best_pos:
                best_pos = p
            break
    return best_pos


def is_excluded(upper_line, keyword_pos, keyword):
    for ex in EXCLUSION_KEYWORDS:
        p = upper_line.find(ex)
        if p >= 0 and p < keyword_pos:
            return True
    if "SUBTOTAL" in upper_line or "SUB TOTAL" in upper_line:
        return True
    if GST_SUMMARY_PAT.search(upper_line):
        return True
    # Column header detection: if the matched keyword is AMOUNT and the line
    # contains TAX / CODE / QTY as fellow header words, treat as header.
    if keyword in ("AMOUNT", "TOTAL"):
        rest = upper_line[keyword_pos + len(keyword):]
        if HEADER_INDICATORS.search(rest):
            return True
    return False


def find_candidates_in_text(text):
    """Return list of (priority, line_idx, value, line) candidates."""
    lines = text.split("\n")
    candidates = []
    for i, line in enumerate(lines):
        upper = line.upper()
        for prio, kws in KEYWORD_TIERS:
            pos = line_matches_keyword(upper, kws)
            if pos is None:
                continue
            # Determine matched keyword text for header-check
            matched_kw = None
            for kw in kws:
                p = upper.find(kw)
                if p == pos:
