        last_v = tier[-1][2]
        chosen = last_v if last_v >= max_v * Decimal("0.8") else max_v
        best_per_variant.append((best_prio, chosen))
        freq[(best_prio, chosen)] += 1

    if not best_per_variant:
        return None

    best_prio = min(bp[0] for bp in best_per_variant)
    # Among top-priority candidates, pick most frequent, then largest value
    top_candidates = [(v, freq[(best_prio, v)])
