    if keyword in ("AMOUNT", "TOTAL"):
        rest = upper_line[keyword_pos + len(keyword):]
        if HEADER_INDICATORS.search(rest):
            return True
    return False


def find_candidates_in_text(text):
    """Return list of (priority, line_idx, value, line) candidates."""
    lines = text.split("\n")
    candidates = []
    for i, line in enumerate(lines):
        upper = line.upper()
        for prio, kws in KEYWORD_TIERS:
            pos = line_matches_keyword(upper, kws)
            if pos is None:
                continue
            # Determine matched keyword text for header-check
            matched_kw = None
            for kw in kws:
                p = upper.find(kw)
                if p == pos:
                    matched_kw = kw
                    break
            if matched_kw is None:
                continue
            if is_excluded(upper, pos, matched_kw):
                continue
            # Search for a number AFTER the keyword on the same line
            after = line[pos + len(matched_kw):]
            nums = NUMBER_PAT.findall(after)
            value = None
            if nums:
                value = parse_amount(nums[-1])
            if value is None or value <= 0:
                # Try next few non-empty, non-noise lines
                for j in range(i + 1, min(i + 4, len(lines))):
                    nxt_raw = lines[j].strip()
                    if not nxt_raw:
                        continue
                    # Skip visually-noise lines (mostly non-alnum)
                    alnum = sum(1 for ch in nxt_raw if ch.isalnum())
                    if alnum < 2:
                        continue
                    nxt_nums = NUMBER_PAT.findall(nxt_raw)
                    if nxt_nums:
                        value = parse_amount(nxt_nums[-1])
                    break
            if value is None or value <= 0:
                continue
            candidates.append((prio, i, value, line))
            break  # only match best-priority keyword tier per line
    return candidates


def extract_amount(texts):
    """Pick the best amount across all OCR variants."""
    # Aggregate candidates across variants
    aggregated = []  # list of (priority, score, value, line)
    # Also tally frequency: how often each (priority, value) appears across variants
    freq = Counter()
    best_per_variant = []
    for text in texts:
        text = normalize_text(text)
        cands = find_candidates_in_text(text)
        if not cands:
            continue
        best_prio = min(c[0] for c in cands)
        tier = [c for c in cands if c[0] == best_prio]
        max_v = max(c[2] for c in tier)
        last_v = tier[-1][2]
        chosen = last_v if last_v >= max_v * Decimal("0.8") else max_v
        best_per_variant.append((best_prio, chosen))
        freq[(best_prio, chosen)] += 1

