DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})\s*[/\-\.]\s*(\d{1,2})\s*[/\-\.]\s*(\d{4})\b"), "dmy4"),
    (re.compile(r"\b(\d{4})\s*[/\-\.]\s*(\d{1,2})\s*[/\-\.]\s*(\d{1,2})\b"), "ymd"),
    (re.compile(r"\b(\d{1,2})\s*[/\-]\s*(\d{1,2})\s*[/\-]\s*(\d{2})\b"), "dmy2"),
    (re.compile(
        r"\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})\b",
        re.IGNORECASE), "dmy_text"),
]


def try_date(d, mo, y):
    if y < 100:
        y = 2000 + y if y < 50 else 1900 + y
    if mo > 12 and d <= 12:
        d, mo = mo, d
    try:
        dt = date(y, mo, d)
    except ValueError:
        return None
    if not (2000 <= y <= 2030):
        return None
    return dt.isoformat()


def extract_date(texts):
    """Collect date candidates across variants; pick by consensus/score."""
    candidates = Counter()  # iso -> count
    day_width = {}  # iso -> average day digit count

    for text in texts:
        text = normalize_text(text)
        seen_in_this_text = set()
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(text):
                g = m.groups()
                try:
                    if kind == "dmy4":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                        dd_width = len(g[0])
                    elif kind == "ymd":
                        y, mo, d = int(g[0]), int(g[1]), int(g[2])
                        dd_width = len(g[2])
                    elif kind == "dmy2":
                        d, mo, y = int(g[0]), int(g[1]), int(g[2])
                        dd_width = len(g[0])
                    elif kind == "dmy_text":
                        d = int(g[0])
                        mo = MONTHS[g[1].lower()[:3]]
                        y = int(g[2])
                        dd_width = len(g[0])
                    iso = try_date(d, mo, y)
                    if iso and iso not in seen_in_this_text:
                        candidates[iso] += 1
                        seen_in_this_text.add(iso)
                        day_width[iso] = max(day_width.get(iso, 0), dd_width)
                except Exception:
                    pass

    if not candidates:
        return None

    # Pick: higher count, then higher day_width (prefer "30" over "3"), then earliest
    best = sorted(
        candidates.items(),
        key=lambda kv: (-kv[1], -day_width.get(kv[0], 1), kv[0]),
    )[0][0]
    return best


# ------------------------- Amount -------------------------

KEYWORD_TIERS = [
    (1, ["GRAND TOTAL"]),
    (2, ["TOTAL RM", "TOTAL: RM"]),
    (3, ["TOTAL AMOUNT"]),
    (4, ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
         "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"]),
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "SST", "DISCOUNT",
    "CHANGE", "CASH TENDERED",
]

GST_SUMMARY_PAT = re.compile(r"\d+(?:\.\d+)?\s*%\s*GST", re.IGNORECASE)

GST_OK_PAT = re.compile(
    r"(incl(?:udes?|usive|\.?)|including)\.?\s*(?:of\s+)?GST",
    re.IGNORECASE)

# Column-header indicator: lines like "Code Qty @ U/(RM) GST Total (RM)" or "Code Amount Tax"
HEADER_INDICATORS = re.compile(
    r"\b(TAX\b|CODE\b|QTY\b|QUANTITY\b|U/\(RM\)|UNIT\b|PRICE\b|RATE\b)",
    re.IGNORECASE)

NUMBER_PAT = re.compile(
    r"\d{1,3}(?:,\d{3})+\.\d{1,2}|\d+\.\d{1,2}|\d+,\d{2}(?!\d)")


def parse_amount(s):
    s = s.strip().replace(" ", "")
    s = re.sub(r"^RM", "", s, flags=re.IGNORECASE)
    if "." in s and "," in s:
        s = s.replace(",", "")
    elif "," in s:
        parts = s.split(",")
        if len(parts) == 2 and len(parts[1]) == 2:
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return Decimal(s)
    except Exception:
        return None


def line_matches_keyword(upper_line, keywords):
    best_pos = None
    for kw in keywords:
        start = 0
        while True:
            p = upper_line.find(kw, start)
            if p < 0:
                break
            # Avoid matching "TOTAL" that's actually part of "SUBTOTAL" / "SUB TOTAL"
            if kw == "TOTAL":
                if p >= 3 and upper_line[p - 3:p] == "SUB":
                    start = p + 1
                    continue
                if p >= 4 and upper_line[p - 4:p] == "SUB ":
                    start = p + 1
                    continue
            if best_pos is None or p < best_pos:
                best_pos = p
            break
    return best_pos


def is_excluded(upper_line, keyword_pos, keyword):
    for ex in EXCLUSION_KEYWORDS:
        p = upper_line.find(ex)
        if p >= 0 and p < keyword_pos:
            return True
    if "SUBTOTAL" in upper_line or "SUB TOTAL" in upper_line:
        return True
    if GST_SUMMARY_PAT.search(upper_line):
        return True
    # Column header detection: if the matched keyword is AMOUNT and the line
    # contains TAX / CODE / QTY as fellow header words, treat as header.
    if keyword in ("AMOUNT", "TOTAL"):
        rest = upper_line[keyword_pos + len(keyword):]
        if HEADER_INDICATORS.search(rest):
            return True
    return False


def find_candidates_in_text(text):
    """Return list of (priority, line_idx, value, line) candidates."""
    lines = text.split("\n")
    candidates = []
    for i, line in enumerate(lines):
        upper = line.upper()
        for prio, kws in KEYWORD_TIERS:
            pos = line_matches_keyword(upper, kws)
            if pos is None:
                continue
            # Determine matched keyword text for header-check
            matched_kw = None
            for kw in kws:
                p = upper.find(kw)
                if p == pos:
                    matched_kw = kw
                    break
            if matched_kw is None:
                continue
            if is_excluded(upper, pos, matched_kw):
                continue
            # Search for a number AFTER the keyword on the same line
            after = line[pos + len(matched_kw):]
            nums = NUMBER_PAT.findall(after)
            value = None
            if nums:
                value = parse_amount(nums[-1])
            if value is None or value <= 0:
                # Try next few non-empty, non-noise lines
                for j in range(i + 1, min(i + 4, len(lines))):
                    nxt_raw = lines[j].strip()
                    if not nxt_raw:
                        continue
                    # Skip visually-noise lines (mostly non-alnum)
                    alnum = sum(1 for ch in nxt_raw if ch.isalnum())
                    if alnum < 2:
                        continue
                    nxt_nums = NUMBER_PAT.findall(nxt_raw)
                    if nxt_nums:
                        value = parse_amount(nxt_nums[-1])
                    break
            if value is None or value <= 0:
                continue
            candidates.append((prio, i, value, line))
            break  # only match best-priority keyword tier per line
    return candidates


def extract_amount(texts):
    """Pick the best amount across all OCR variants."""
    # Aggregate candidates across variants
    aggregated = []  # list of (priority, score, value, line)
    # Also tally frequency: how often each (priority, value) appears across variants
    freq = Counter()
    best_per_variant = []
    for text in texts:
        text = normalize_text(text)
        cands = find_candidates_in_text(text)
        if not cands:
            continue
        best_prio = min(c[0] for c in cands)
        tier = [c for c in cands if c[0] == best_prio]
        max_v = max(c[2] for c in tier)
        last_v = tier[-1][2]
        chosen = last_v if last_v >= max_v * Decimal("0.8") else max_v
        best_per_variant.append((best_prio, chosen))
        freq[(best_prio, chosen)] += 1

    if not best_per_variant:
        return None

    best_prio = min(bp[0] for bp in best_per_variant)
    # Among top-priority candidates, pick most frequent, then largest value
    top_candidates = [(v, freq[(best_prio, v)])
                      for p, v in best_per_variant if p == best_prio]
    # Dedupe
    unique_vals = {}
    for v, c in top_candidates:
        unique_vals[v] = max(unique_vals.get(v, 0), c)
    chosen = sorted(unique_vals.items(), key=lambda kv: (-kv[1], -kv[0]))[0][0]
    return f"{chosen:.2f}"


# ------------------------- Main -------------------------

def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        texts = ocr_variants(path)
        d = extract_date(texts)
        a = extract_amount(texts)
        print(f"{fname}: date={d}, amount={a}")
        rows.append({"filename": fname, "date": d, "total_amount": a})

    df = pd.DataFrame(rows, columns=["filename", "date", "total_amount"])
    df.to_excel(OUT_XLSX, sheet_name="results", index=False)
    print(f"Wrote {OUT_XLSX}")


if __name__ == "__main__":
    main()
